 if !ok || evidence["old_typed_rows_unchanged"]!=true || evidence["restored_barriers_refreshed"]!=false{t.Fatal("missing distinct session phase receipt")}
 _,_,_,target:=restored21FixtureProfiles(t,opt);db:=restored21Open(t,filepath.Join(opt.Destination,"researchos.sqlite"));got,err:=backupSchema(db);if err!=nil || got!=target{t.Fatalf("target profile %s %v",got,err)}
